@IsTest private class OwnerContactObservation {
private static Map<String,Object> observe(Id caseId,User directOwner) {
    Map<String,Object> answer=new Map<String,Object>();
    List<String> fields=new List<String>{'Id','Name','FirstName','LastName','Phone','Email'};
    answer.put('fields',fields);
    Map<String,Object> combined=new Map<String,Object>{'q'=>false};
    String stage='inlineQuery';
    try {
        List<Case> rows=[SELECT Id,OwnerId,Owner.Id,Owner.Name,Owner.FirstName,Owner.LastName,Owner.Phone,Owner.Email FROM Case WHERE Id=:caseId WITH USER_MODE];
        combined.put('q',true);combined.put('n',rows.size());stage='readOwner';
        if (!rows.isEmpty()) {
            SObject owner=rows[0].getSObject('Owner');combined.put('z',owner==null);
            List<Boolean> nullFlags=new List<Boolean>();List<Boolean> matches=new List<Boolean>();
            stage='readFields';
            for (String field:fields) {
                Object value=owner==null?null:owner.get(field);nullFlags.add(value==null);
                matches.add(directOwner==null?null:value==directOwner.get(field));
            }
            combined.put('null',nullFlags);combined.put('eq',matches);
        }
    } catch(Exception e) {combined.put('e',new List<String>{stage,e.getTypeName()});}
    answer.put('c',combined);
    Map<String,Object> individual=new Map<String,Object>();
    List<String> probes=new List<String>();probes.addAll(fields);probes.add('MissingSynthetic__c');
    for(String field:probes) {
        Boolean queried=false;Integer count=null;stage='dynamicQuery';
        try {
            List<SObject> rows=Database.query('SELECT Id,Owner.'+field+' FROM Case WHERE Id=:caseId WITH USER_MODE');
            queried=true;count=rows.size();stage='readOwner';
            SObject owner=rows.isEmpty()?null:rows[0].getSObject('Owner');stage='readField';
            Object value=owner==null?null:owner.get(field);
            individual.put(field,new List<Object>{true,count,owner==null,value==null,directOwner==null?null:value==directOwner.get(field)});
        } catch(Exception e) {
            individual.put(field,queried?new List<Object>{true,count,stage,e.getTypeName()}:new List<Object>{false,e.getTypeName()});
        }
    }
    answer.put('d',individual);answer.put('stage','complete');return answer;
}
private static User makeOwner() {
    Id currentId=UserInfo.getUserId();
    User t=[SELECT ProfileId,TimeZoneSidKey,LocaleSidKey,EmailEncodingKey,LanguageLocaleKey FROM User WHERE Id=:currentId];
    User u=new User(FirstName='Atlas',LastName='Observer',Phone='5550102',Email='atlas@example.invalid',Alias='ownerobs',Username=String.valueOf(DateTime.now().getTime())+'.'+UserInfo.getOrganizationId()+'.ownercontact@example.invalid',ProfileId=t.ProfileId,TimeZoneSidKey=t.TimeZoneSidKey,LocaleSidKey=t.LocaleSidKey,EmailEncodingKey=t.EmailEncodingKey,LanguageLocaleKey=t.LanguageLocaleKey);
    insert u;return u;
}
@IsTest static void userOwned() {
    User u=makeOwner();
    System.runAs(u) {
        Id uid=u.Id;User directOwner=[SELECT Id,Name,FirstName,LastName,Phone,Email FROM User WHERE Id=:uid WITH USER_MODE];
        Case c=new Case(Subject='Owned contact observation',Status='New',Origin='Phone',OwnerId=uid);insert c;
        Map<String,Object> answer=observe(c.Id,directOwner);answer.put('sourceApi','61.0');answer.put('context','@IsTest');answer.put('owner','User');
        System.assert(false,'OWNER_CONTACT_OBSERVATION|'+JSON.serialize(answer));
    }
}
@IsTest static void queueOwned() {
    Map<String,Object> answer=new Map<String,Object>{'sourceApi'=>'61.0','context'=>'@IsTest','owner'=>'Queue'};
    try {
        Group q=new Group(Name='Owned Contact Probe',DeveloperName='OwnedContactProbe'+String.valueOf(DateTime.now().getTime()),Type='Queue');insert q;
        insert new QueueSobject(QueueId=q.Id,SobjectType='Case');
        System.runAs(new User(Id=UserInfo.getUserId())) {
            Case c=new Case(Subject='Owned queue contact observation',Status='New',Origin='Phone',OwnerId=q.Id);insert c;
            answer.putAll(observe(c.Id,null));
        }
    } catch(Exception e) {answer.put('e',new List<String>{'queueSetup',e.getTypeName()});}
    System.assert(false,'OWNER_CONTACT_OBSERVATION|'+JSON.serialize(answer));
}
}

